// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 timestamp1, uint256 timestamp2) public {
        vm.assume(timestamp1 < timestamp2);

        // First call to set pastBlockTime
        vm.warp(timestamp1);
        vm.deal(address(this), 10 ether);
        (bool success1, ) = address(c).call{value: 10 ether}("");

        // Second call with same timestamp (should revert in reference but pass in mutant)
        vm.warp(timestamp1); // same timestamp
        vm.deal(address(this), 10 ether);
        (bool success2, ) = address(c).call{value: 10 ether}("");

        // In reference: success2 must be false because block.timestamp == pastBlockTime
        // In mutant: success2 may be true
        assertTrue(!success2, "Second call should revert when timestamps are equal");
    }
}

